// 1. Get all the news items using the new "$input.all()" command
const allTitles = $input.all().map(item => item.json.title).join("\n");

// 2. Return them as one single combined item
return {
  json: {
    combined_news: allTitles
  }
};

// Get the text answer from Gemini
const aiText = $input.first().json.content.parts[0].text;

// Clean it up (remove any accidental markdown formatting)
const cleanText = aiText.replace(/```json|```/g, "").trim();

// Convert text to real Data
return {
  json: JSON.parse(cleanText)
};

/* ---------------------------------------------------
   1. GATHER INPUTS
--------------------------------------------------- */
const input = $input.first().json;

// Golden patterns: [ ["STABLE","STABLE","PUMP_SMALL"], ... ]
const patterns = Array.isArray(input.patterns) ? input.patterns : [];

// Market data
const btcPrice = Number(input.btc_price_inr);
const volatility = Number(input.volatility_percent);
const sentimentScore = Number(input.sentiment_score);
const isPanic = input.is_panic === true;
const recent = Array.isArray(input.recent_trends) ? input.recent_trends : [];

/* ---------------------------------------------------
   2. PROFITABILITY CHECK (INDIA REALITY)
--------------------------------------------------- */
const INVESTMENT = 10000;
let isProfitable = false;
let netProfit = 0;
let targetUsed = "0%";
let targetReason = "No edge";

try {
    const targetPct = volatility; // REAL market movement

    const targetMultiplier = 1 + targetPct / 100;
    const sellValue = (INVESTMENT / btcPrice) * (btcPrice * targetMultiplier);

    const tds = sellValue * 0.01;
    const gross = sellValue - INVESTMENT - tds;
    const tax = gross > 0 ? gross * 0.30 : 0;

    netProfit = gross - tax;
    isProfitable = netProfit > 0;
    targetUsed = targetPct.toFixed(2) + "%";

    targetReason =
        targetPct < 1.5
            ? `⚠️ Volatility (${targetPct.toFixed(2)}%) below tax break-even`
            : `✅ Volatility (${targetPct.toFixed(2)}%) supports scalp`;

} catch (e) {
    isProfitable = false;
}

/* ---------------------------------------------------
   3. GOLDEN PATTERN MATCHING (CORRECT)
--------------------------------------------------- */
function key(arr) {
    return arr.join("|");
}

const recentKey = key(recent);
let patternMatched = false;

for (const p of patterns) {
    if (!Array.isArray(p)) continue;
    if (key(p) === recentKey) {
        patternMatched = true;
        break;
    }
}

/* ---------------------------------------------------
   4. DECISION ENGINE
--------------------------------------------------- */
let decision = "HOLD";

// Absolute risk condition
if (isPanic) {
    decision = "SELL";
}

// Only BUY if ALL conditions align
else if (
    patternMatched &&          // statistical edge
    isProfitable &&            // can beat taxes
    sentimentScore >= 4        // not bearish
) {
    decision = "BUY";
}

// Soft HOLD zones
else if (sentimentScore <= 3) {
    decision = "SELL";
}

/* ---------------------------------------------------
   5. OUTPUT (TELEGRAM READY)
--------------------------------------------------- */
return {
    json: {
        timestamp: new Date().toLocaleString("en-IN", { timeZone: "Asia/Kolkata" }),
        decision,

        pattern: {
            recent_sequence: recent.length ? recent.join(" ➡️ ") : "No data",
            match_status: patternMatched ? "✅ Golden Pattern" : "❌ No Pattern"
        },

        sentiment: {
            score: sentimentScore,
            analysis: input.reason,
            is_panic: isPanic
        },

        risk: {
            panic: isPanic,
            sentiment_score: sentimentScore
        },

        market_data: {
            price_inr: btcPrice,
            volatility_3h: volatility,
            real_usd_rate: input.real_usd_rate,
            usdt_price: input.usdt_price_inr,
            premium: input.premium_percent
        },

        financials: {
            investment: INVESTMENT,
            target_used: targetUsed,
            projected_profit: Number(netProfit.toFixed(2)),
            profitable: isProfitable,
            reason: targetReason
        }
    }
};

