// 1. Get data from previous nodes
// Note: You might need to check your node names if they are different!
const btcData = $('Bitcoin Price Check').first().json;      // The first node (BTC)
const forexData = $('USD Rate').first().json;   // The second node (Forex)
const usdtData = $('USD to INR Rate').first().json;    // The third node (USDT)

// 2. Extract specific numbers
const btcPrice = parseFloat(btcData.lastPrice);
const realUsd = forexData.rates.INR;
const usdtPrice = parseFloat(usdtData.lastPrice);

// 3. Do the Math
const premium = ((usdtPrice - realUsd) / realUsd) * 100;

// 4. Output the result
return {
  json: {
    btc_price_inr: btcPrice,
    real_usd_rate: realUsd,
    usdt_price_inr: usdtPrice,
    premium_percent: premium.toFixed(2) + "%", // e.g. "3.50%"
    is_panic: premium > 5 // True if premium is high
  }
};

/* ---------------------------------------------------
   TRANSLATOR: RAW DATA -> TRENDS & VOLATILITY
   ---------------------------------------------------
*/
const items = $('Get History').all();

// Helper to check trends
function getTrend(open, close) {
    const diff = ((close - open) / open) * 100;
    if (diff >= 1.5) return "PUMP_HUGE";
    if (diff <= -1.5) return "DUMP_HUGE";
    if (diff >= 0.3) return "PUMP_SMALL";
    if (diff <= -0.3) return "DUMP_SMALL";
    return "STABLE";
}

// 1. Calculate Trends & Volatility
let totalVolatility = 0;

const trends = items.map(item => {
    // Keep raw values for calculation
    const row = item.json;

    const open  = row[1];
    const high  = row[2];
    const low   = row[3];
    const close = row[4];


    // Add to volatility sum
    totalVolatility += ((high - low) / open) * 100;

    return getTrend(open, close);
});

// Calculate Average
const avgVolatility = totalVolatility / items.length;

// Output RAW values (No defaults)
return {
    json: {
        recent_trends: trends,
        volatility_percent: avgVolatility
    }
};
